import{_ as t,o,c as i,a2 as n}from"./chunks/framework.BBXLvvRa.js";const u=JSON.parse('{"title":"Manifesto Principles","description":"The four principles of the BPM Manifesto, each explained in depth for BPM developers, consultants, and architects.","frontmatter":{"title":"Manifesto Principles","description":"The four principles of the BPM Manifesto, each explained in depth for BPM developers, consultants, and architects."},"headers":[],"relativePath":"docs/principles/index.md","filePath":"docs/principles/index.md"}'),r={name:"docs/principles/index.md"};function s(a,e,p,l,c,d){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="manifesto-principles" tabindex="-1">Manifesto Principles <a class="header-anchor" href="#manifesto-principles" aria-label="Permalink to &quot;Manifesto Principles&quot;">​</a></h1><p>The <a href="/">BPM Manifesto</a> is built on four principles. Each follows the same pattern: it names something we value <strong>more</strong> over something we value <strong>less</strong>.</p><p>As in the <a href="https://agilemanifesto.org/" target="_blank" rel="noreferrer">Agile Manifesto</a>, the items on the right still have value. We simply value the items on the left more. The pages below explain what each principle means in day-to-day process automation work, why it matters, and how to put it into practice.</p><h2 id="the-four-principles" tabindex="-1">The four principles <a class="header-anchor" href="#the-four-principles" aria-label="Permalink to &quot;The four principles&quot;">​</a></h2><ul><li><p><a href="/docs/principles/business-it-alignment"><strong>Fostering Business-IT Alignment</strong> over Developer-driven Process Automation</a><br>Keep automated processes anchored in a shared understanding of the business domain.</p></li><li><p><a href="/docs/principles/open-standards"><strong>Open Standards</strong> over Proprietary Solutions</a><br>Build on open, interoperable specifications so your models outlive any single tool.</p></li><li><p><a href="/docs/principles/best-practices"><strong>Process Automation Best Practices</strong> over Tool-Centric Features</a><br>Let proven methods and patterns drive your architecture, not a vendor&#39;s feature list.</p></li><li><p><a href="/docs/principles/continuous-improvement"><strong>Continuous Process Improvement</strong> over Scoped and Time-Boxed Targets</a><br>Treat automation as an ongoing product, not a one-off project.</p></li></ul>',5)])])}const f=t(r,[["render",s]]);export{u as __pageData,f as default};
